        { type: 'one', q: 'Что такое компромисс?', a: ['Победить любой ценой', 'Каждый немного уступает ради общего решения', 'Всегда уступать другу', 'Перестать общаться'], c: 1, why: 'Компромисс — найти середину, где учтены оба.' },
        { type: 'one', q: 'Какая фраза — аргумент?', a: ['«Потому что я так хочу»', '«Давай в прятки: тут много мест, всем интересно»', '«Ты всё равно не прав»', '«Кто не со мной, тот лузер»'], c: 1, why: 'Аргумент объясняет причину.' },
        { type: 'order', q: 'Расставь шаги, как договориться в споре.', items: ['Спокойно сказать, чего хочешь и почему', 'Выслушать другую сторону', 'Предложить варианты', 'Выбрать решение, где рады оба', 'Не вышло — очередь или жребий'], why: 'Сказать → выслушать → придумать → выбрать.' },
        { type: 'sort', q: 'Честный способ решить спор или нет?', groups: ['Честно', 'Нечестно'], items: [['Камень-ножницы-бумага', 0], ['По очереди', 0], ['Кто сильнее, тот и прав', 1], ['Считалочка', 0], ['Перекричать всех', 1], ['Обидеться, пока не уступят', 1]], why: 'Честный способ даёт равные шансы всем.' },
        { type: 'tf', q: 'Если вы спорите, значит, вы больше не друзья.', c: false, why: 'Друзья тоже спорят. Важно делать это уважительно.' },
        { type: 'tf', q: 'Лучшее решение — то, где выиграли оба.', c: true, why: 'Тогда никто не обижен, и все довольны.' }
