        { type: 'case', story: 'Ты толкнул одноклассника в коридоре, он упал. Ты хочешь извиниться.', q: 'Какое извинение настоящее?', a: [
          { t: '«Прости, но ты сам стоял на дороге»', ok: false, why: '«Но» перечёркивает извинение — это обвинение.' },
          { t: '«Прости, я толкнул тебя. Ты не ушибся? Давай помогу»', ok: true, why: 'Верно! Признал, позаботился, помог.' },
          { t: '«Извини, если тебе больно»', ok: 'mid', why: 'Почти, но «если» звучит неуверенно. Признай прямо.' }
        ], why: 'Никаких «но» и «если» — признаём, что сделали.' },
        { type: 'case', story: 'Друг извинился, но тебе ещё очень обидно — он рассказал твой секрет.', q: 'Как ответишь честно?', a: [
          { t: '«Спасибо, что сказал. Мне нужно немного времени»', ok: true, why: 'Честно и по-доброму. Ты не отталкиваешь, но и не притворяешься.' },
          { t: '«Ничего страшного!» — и злиться дальше', ok: 'mid', why: 'Друг решит, что всё хорошо, а обида останется внутри.' },
          { t: '«Не прощу никогда!»', ok: false, why: 'Слишком резко. Может, через пару дней тебе станет легче.' }
        ], why: 'Можно честно попросить время, чтобы обида прошла.' },
        { type: 'order', q: 'Расставь шаги настоящего извинения.', items: ['Подойти и посмотреть в глаза', 'Признать: «Я сделал…»', 'Сказать: «Мне жаль»', 'Предложить исправить', 'Не повторять ошибку'], why: 'Признать → сожалеть → исправить → не повторять.' },
        { type: 'one', q: 'Какое извинение настоящее?', a: ['«Ну сорян»', '«Прости, но ты первый начал»', '«Я сломал твою машинку. Прости, я починю»', '«Извини, если обиделся»'], c: 2, why: 'В нём есть все три части: признание, сожаление, исправление.' },
        { type: 'one', q: 'Что перечёркивает извинение?', a: ['Слово «прости»', 'Слово «но» после «прости»', 'Взгляд в глаза', 'Предложение помочь'], c: 1, why: '«Прости, но…» превращает извинение в оправдание.' },
        { type: 'sort', q: 'Помогает помириться или мешает?', groups: ['Помогает', 'Мешает'], items: [['Записка «Давай мириться?»', 0], ['Вспоминать старые обиды', 1], ['Признать свою часть вины', 0], ['Требовать, чтобы извинился первым', 1], ['Предложить вместе поиграть', 0], ['Жаловаться всем подряд', 1]], why: 'Мирятся шагом навстречу, а не счётом обид.' },
        { type: 'tf', q: 'Помириться первым — значит проиграть.', c: false, why: 'Это смелость. Выигрывает дружба.' },
        { type: 'tf', q: 'Извинение лучше, если предложить исправить ошибку.', c: true, why: 'Дела показывают, что ты сожалеешь по-настоящему.' }
